import pathlib

from experiment_datadefinitions.renderer.renderer_cpp import RendererCPP

from app_emw.datamodel import datamodels_emw

DIRECTORY_OF_THIS_FILE = pathlib.Path(__file__).resolve().parent
DIRECTORY_ZEPHYR_SRC = DIRECTORY_OF_THIS_FILE.parents[3] / "zephyr" / "src"

FILE_HEADER = """\
#pragma once

// Generated by main_codegeneration.py - do not edit!

#include <cstdint>
"""


def main() -> int:
    assert DIRECTORY_ZEPHYR_SRC.is_dir(), DIRECTORY_ZEPHYR_SRC

    # Nested models are only referenced: Include the headers of
    # ModelM7StatusChannel before the headers of ModelM7Status!
    for model in (
        datamodels_emw.ModelImuStatus(),
        datamodels_emw.ModelM7StatusChannel(),
        datamodels_emw.ModelM7Status(),
    ):
        renderer = RendererCPP(model=model)

        for filename, source in (
            (renderer.filename_struct, renderer.render_cpp_struct()),
            (renderer.filename_initializer, renderer.render_cpp_initializer()),
        ):
            output_file = DIRECTORY_ZEPHYR_SRC / filename
            output_file.write_text(FILE_HEADER + source)
            print(f"Wrote {output_file}")
    return 0


if __name__ == "__main__":
    main()
